@app.route("/logout")
async def logout(request):
    id_token = request.session.pop("id_token", None)
    return await oauth.google.logout_redirect(
        request,
        post_logout_redirect_uri=str(request.url_for("logged_out")),
        id_token_hint=id_token,
    )

