const dropRepeatedRepeat = {
  level1: {
    property: function (_rule, property) {
      if (property.name === 'background-repeat' && property.value.length === 2
        && property.value[0][1] === property.value[1][1]) {
        property.value.pop();
        property.dirty = true;
      }
    }
  }
};

