import array
import msgpack

def default(obj):
    if isinstance(obj, array.array) and obj.typecode == "d":
        return msgpack.ExtType(42, obj.tobytes())
    raise TypeError(f"Unknown type: {obj!r}")

def ext_hook(code, data):
    if code == 42:
        a = array.array("d")
        a.frombytes(data)
        return a
    return msgpack.ExtType(code, data)

