def traces_sampler(sampling_context):
    path = sampling_context.get("asgi_scope", {}).get("path", "")
    if path in ("/health", "/metrics"):
        return 0.0
    if path.startswith("/checkout"):
        return 1.0
    return 0.05

sentry_sdk.init(dsn=DSN, traces_sampler=traces_sampler)

def before_send(event, hint):
    request = event.get("request", {})
    headers = request.get("headers", {})
    for key in ("Authorization", "Cookie", "X-Api-Key"):
        if key in headers:
            headers[key] = "[filtered]"
    if isinstance(hint.get("exc_info"), tuple):
        exc = hint["exc_info"][1]
        if isinstance(exc, ExpectedTimeout):
            return None   # drop the event entirely
    return event

sentry_sdk.init(dsn=DSN, before_send=before_send)

import sentry_sdk

def lambda_handler(event, context):
    try:
        return process(event)
    except Exception:
        sentry_sdk.capture_exception()
        raise
    finally:
        sentry_sdk.flush(timeout=2.0)

